/**
 * Ravae Record - Ingestion & Super Admin Review System
 * Node.js & Browser ES Module Implementation with Google Drive Adapter
 * 
 * Auto-generated by The Backstage Operations Hub
 * Connected to Antigravity Tri-Party Shared Data Sync Engine
 */

export const ROOT_FOLDER_ID = "RAVAE-STUDIO-ROOT";
export const COMPANY_NAME = "Ravae Record";

export const PRODUCER_MAPPING = {
  "Yung Ravae": "VaeDaVisonary",
  "yung ravae": "VaeDaVisonary",
  "Old Ravae": "VaeDaVisonary",
  "OLD RAVAE": "VaeDaVisonary",
  "Ravae Records": "Ravae Record"
};

/**
 * Applies rebranding rules to text inputs and file names.
 * - Replaces "Ravae Records" -> "Ravae Record"
 * - Maps producer aliases ("Yung Ravae", "yung ravae", "Old Ravae", "OLD RAVAE") -> "VaeDaVisonary"
 * 
 * @param {string} textInput
 * @returns {string} Rebranded text
 */
export function applyRavaeRebrandOverrides(textInput) {
  if (!textInput || typeof textInput !== "string") return textInput;
  
  // Replace Ravae Records -> Ravae Record
  let result = textInput.replace(/Ravae Records/g, COMPANY_NAME);
  
  // Map producer aliases -> VaeDaVisonary
  for (const oldAlias in PRODUCER_MAPPING) {
    const regex = new RegExp(oldAlias, "gi");
    result = result.replace(regex, PRODUCER_MAPPING[oldAlias]);
  }
  return result;
}

/**
 * Lightweight iterator conforming to Google Apps Script's FolderIterator / FileIterator interface
 */
class AppsScriptIterator {
  constructor(items = []) {
    this.items = [...items];
    this.currentIndex = 0;
  }

  hasNext() {
    return this.currentIndex < this.items.length;
  }

  next() {
    if (!this.hasNext()) {
      throw new Error("No more elements in iterator");
    }
    return this.items[this.currentIndex++];
  }
}

/**
 * Virtual Google Drive File conforming to Google Apps Script Drive File
 */
export class VirtualDriveFile {
  constructor({ id, name, content = null, description = "", parentFolder = null }) {
    this.id = id || `file_${Date.now()}_${Math.random().toString(36).substr(2, 6)}`;
    this.name = name;
    this.content = content;
    this.description = description;
    this.parentFolder = parentFolder;
    this.dateCreated = new Date();
  }

  getId() {
    return this.id;
  }

  getName() {
    return this.name;
  }

  setName(newName) {
    this.name = newName;
    return this;
  }

  getDescription() {
    return this.description;
  }

  setDescription(newDescription) {
    this.description = newDescription;
    return this;
  }

  getUrl() {
    return `https://drive.google.com/open?id=${this.id}`;
  }

  getDateCreated() {
    return this.dateCreated;
  }

  moveTo(targetFolder) {
    if (this.parentFolder) {
      this.parentFolder.files = this.parentFolder.files.filter(f => f.getId() !== this.id);
    }
    this.parentFolder = targetFolder;
    targetFolder.files.push(this);
    return this;
  }
}

/**
 * Virtual Google Drive Folder conforming to Google Apps Script Drive Folder
 */
export class VirtualDriveFolder {
  constructor({ id, name, parentFolder = null }) {
    this.id = id || `folder_${Date.now()}_${Math.random().toString(36).substr(2, 6)}`;
    this.name = name;
    this.parentFolder = parentFolder;
    this.subFolders = [];
    this.files = [];
  }

  getId() {
    return this.id;
  }

  getName() {
    return this.name;
  }

  getFolders() {
    return new AppsScriptIterator(this.subFolders);
  }

  getFoldersByName(name) {
    const matches = this.subFolders.filter(f => f.getName().toLowerCase() === name.toLowerCase());
    return new AppsScriptIterator(matches);
  }

  createFolder(name) {
    const existing = this.subFolders.find(f => f.getName().toLowerCase() === name.toLowerCase());
    if (existing) return existing;

    const newFolder = new VirtualDriveFolder({
      name,
      parentFolder: this
    });
    this.subFolders.push(newFolder);
    return newFolder;
  }

  getFiles() {
    return new AppsScriptIterator(this.files);
  }

  createFile(fileBlobOrName, content = "") {
    let name = "unnamed_file";
    let actualContent = content;

    if (fileBlobOrName && typeof fileBlobOrName.getName === "function") {
      name = fileBlobOrName.getName();
      actualContent = typeof fileBlobOrName.getDataAsString === "function" ? fileBlobOrName.getDataAsString() : null;
    } else if (typeof fileBlobOrName === "string") {
      name = fileBlobOrName;
    }

    const file = new VirtualDriveFile({
      name,
      content: actualContent,
      parentFolder: this
    });
    this.files.push(file);
    return file;
  }
}

/**
 * Virtual DriveApp provider for simulation and local execution
 */
export class VirtualDriveApp {
  constructor(rootFolderId = ROOT_FOLDER_ID) {
    this.rootFolderId = rootFolderId;
    this.folders = new Map();
    this.files = new Map();

    // Create root folder
    const root = new VirtualDriveFolder({
      id: rootFolderId,
      name: "RAVAE STUDIO (FILE SYSTEM)"
    });
    this.folders.set(rootFolderId, root);

    // Bootstrap standard directory structure
    this.bootstrapStructure(root);
  }

  bootstrapStructure(root) {
    // 00_Uploads_Pending_Review
    const staging = root.createFolder("00_Uploads_Pending_Review");
    this.folders.set(staging.getId(), staging);
    const prodFolder = staging.createFolder("Producers");
    this.folders.set(prodFolder.getId(), prodFolder);
    const ccFolder = staging.createFolder("Content_Creators");
    this.folders.set(ccFolder.getId(), ccFolder);

    // 01_Catalog
    const catalog = root.createFolder("01_Catalog");
    this.folders.set(catalog.getId(), catalog);
    const beats = catalog.createFolder("Beats");
    this.folders.set(beats.getId(), beats);
    const vaeFolder = beats.createFolder("VaeDaVisonary");
    this.folders.set(vaeFolder.getId(), vaeFolder);
    const releases = root.createFolder("02_Releases");
    this.folders.set(releases.getId(), releases);
  }

  getFolderById(folderId) {
    if (this.folders.has(folderId)) {
      return this.folders.get(folderId);
    }
    // Search recursively from root
    const root = this.folders.get(this.rootFolderId);
    const found = this.searchFolder(root, folderId);
    if (found) {
      this.folders.set(folderId, found);
      return found;
    }
    throw new Error(`DriveApp: Folder with ID "${folderId}" not found.`);
  }

  searchFolder(current, targetId) {
    if (current.getId() === targetId) return current;
    for (const sub of current.subFolders) {
      const match = this.searchFolder(sub, targetId);
      if (match) return match;
    }
    return null;
  }

  getFileById(fileId) {
    const root = this.folders.get(this.rootFolderId);
    const found = this.searchFile(root, fileId);
    if (found) return found;
    throw new Error(`DriveApp: File with ID "${fileId}" not found.`);
  }

  searchFile(folder, targetId) {
    for (const f of folder.files) {
      if (f.getId() === targetId) return f;
    }
    for (const sub of folder.subFolders) {
      const match = this.searchFile(sub, targetId);
      if (match) return match;
    }
    return null;
  }
}

/**
 * Finds or creates a subfolder by path inside a parent folder.
 */
export function getOrCreateFolderByPath(parentFolder, pathSegments) {
  let currentFolder = parentFolder;
  for (let i = 0; i < pathSegments.length; i++) {
    const segment = pathSegments[i];
    const folders = currentFolder.getFoldersByName(segment);
    if (folders.hasNext()) {
      currentFolder = folders.next();
    } else {
      currentFolder = currentFolder.createFolder(segment);
    }
  }
  return currentFolder;
}

/**
 * Ravae Record Ingestion & Super Admin Review System Manager
 * Connects Google Drive operations with Antigravity Tri-Party Shared Data Sync.
 */
export class RavaeRecordSystem {
  constructor({ driveApp = null, rootFolderId = ROOT_FOLDER_ID, syncEngine = null } = {}) {
    this.rootFolderId = rootFolderId;
    this.driveApp = driveApp || new VirtualDriveApp(this.rootFolderId);
    this.syncEngine = syncEngine;
  }

  /**
   * Bind to Antigravity shared sync engine
   */
  bindSyncEngine(syncEngine) {
    this.syncEngine = syncEngine;
    if (this.syncEngine) {
      this.syncEngine.update('workspace', 'ravae.systemStatus', {
        initialized: true,
        rootFolder: this.rootFolderId,
        companyName: COMPANY_NAME,
        timestamp: new Date().toISOString()
      });
      this.syncState();
    }
  }

  /**
   * Synchronize current state to Shared Data store
   */
  syncState() {
    if (!this.syncEngine) return;
    const queue = this.getSuperAdminReviewQueue();
    const tree = this.getFolderStructureSummary();
    this.syncEngine.update('workspace', 'ravae.reviewQueue', queue);
    this.syncEngine.update('workspace', 'ravae.fileSystem', tree);
  }

  /**
   * UPLOAD NEW WORKS (Producer / Creator Ingestion Endpoint)
   * Uploads file directly to '00_Uploads_Pending_Review' staging folder.
   */
  uploadNewWork(creatorName, role, fileName, rightsTier, fileBlobOrData = null) {
    const rootFolder = this.driveApp.getFolderById(this.rootFolderId);
    
    // Apply rebranding overrides
    const cleanCreator = applyRavaeRebrandOverrides(creatorName);
    const cleanFileName = applyRavaeRebrandOverrides(fileName);
    
    // Determine subfolder based on role
    const roleStr = (role || "").toString().toLowerCase();
    const isProducer = roleStr === "producer" || roleStr.includes("beat") || roleStr.includes("instrumental");
    const roleFolder = isProducer ? "Producers" : "Content_Creators";
    const stagingFolder = getOrCreateFolderByPath(rootFolder, ["00_Uploads_Pending_Review", roleFolder]);
    
    // Prepare file
    let stagedFile;
    if (fileBlobOrData && typeof fileBlobOrData.setName === "function") {
      fileBlobOrData.setName(cleanFileName);
      stagedFile = stagingFolder.createFile(fileBlobOrData);
    } else {
      stagedFile = stagingFolder.createFile(cleanFileName, fileBlobOrData || "Audio/Media Content Data");
    }
    
    // Apply custom metadata properties
    const description = 
      "STATUS: PENDING_SUPER_ADMIN_REVIEW\n" +
      "Creator: " + cleanCreator + "\n" +
      "Role: " + role + "\n" +
      "Rights Tier: " + rightsTier;
    stagedFile.setDescription(description);
    
    const result = {
      status: "SUCCESS",
      fileId: stagedFile.getId(),
      fileName: cleanFileName,
      creator: cleanCreator,
      originalCreator: creatorName,
      role,
      roleFolder,
      rightsTier,
      url: stagedFile.getUrl(),
      dateCreated: stagedFile.getDateCreated()
    };

    if (this.syncEngine) {
      this.syncEngine.update('workspace', `ravae.uploads.${result.fileId}`, result);
      this.syncState();
    }
    
    return result;
  }

  /**
   * SUPER ADMIN: Get Pending Review Queue
   * Fetches all files currently awaiting approval in staging.
   */
  getSuperAdminReviewQueue() {
    const rootFolder = this.driveApp.getFolderById(this.rootFolderId);
    const stagingFolder = getOrCreateFolderByPath(rootFolder, ["00_Uploads_Pending_Review"]);
    
    const pendingQueue = [];
    const subFolders = stagingFolder.getFolders();
    
    while (subFolders.hasNext()) {
      const subFolder = subFolders.next();
      const files = subFolder.getFiles();
      while (files.hasNext()) {
        const file = files.next();
        const desc = file.getDescription() || "";
        
        // Parse metadata from description
        const creatorMatch = desc.match(/Creator:\s*([^\n]+)/i);
        const roleMatch = desc.match(/Role:\s*([^\n]+)/i);
        const tierMatch = desc.match(/Rights Tier:\s*([^\n]+)/i);
        const statusMatch = desc.match(/STATUS:\s*([^\n]+)/i);

        pendingQueue.push({
          fileId: file.getId(),
          fileName: file.getName(),
          folderName: subFolder.getName(),
          description: desc,
          status: statusMatch ? statusMatch[1].trim() : "PENDING_SUPER_ADMIN_REVIEW",
          creator: creatorMatch ? creatorMatch[1].trim() : "Unknown",
          role: roleMatch ? roleMatch[1].trim() : "Producer",
          rightsTier: tierMatch ? tierMatch[1].trim() : "Standard",
          url: file.getUrl(),
          dateCreated: file.getDateCreated()
        });
      }
    }
    
    return pendingQueue;
  }

  /**
   * SUPER ADMIN: Approve & Move Beat
   * Moves approved beat from staging to target Google Drive catalog path.
   */
  approveAndCatalogBeat(fileId, targetPathSegments = ["01_Catalog", "Beats", "VaeDaVisonary"]) {
    const file = this.driveApp.getFileById(fileId);
    const rootFolder = this.driveApp.getFolderById(this.rootFolderId);
    
    // Ensure target folder exists
    const targetFolder = getOrCreateFolderByPath(rootFolder, targetPathSegments);
    
    // Move file to final target folder
    file.moveTo(targetFolder);
    
    // Update description status
    const currentDesc = file.getDescription() || "";
    file.setDescription(currentDesc.replace("PENDING_SUPER_ADMIN_REVIEW", "APPROVED"));
    
    const result = {
      status: "APPROVED",
      fileId,
      fileName: file.getName(),
      targetPath: targetPathSegments.join("/"),
      newUrl: file.getUrl(),
      approvedAt: new Date().toISOString()
    };

    if (this.syncEngine) {
      this.syncEngine.update('workspace', `ravae.approved.${fileId}`, result);
      this.syncState();
    }
    
    return result;
  }

  /**
   * Visual folder hierarchy representation of RAVAE STUDIO
   */
  getFolderStructureSummary() {
    const root = this.driveApp.getFolderById(this.rootFolderId);
    
    function traverse(folder) {
      const node = {
        name: folder.getName(),
        id: folder.getId(),
        files: [],
        folders: []
      };

      const files = folder.getFiles();
      while (files.hasNext()) {
        const f = files.next();
        node.files.push({
          id: f.getId(),
          name: f.getName(),
          description: f.getDescription()
        });
      }

      const subFolders = folder.getFolders();
      while (subFolders.hasNext()) {
        const sub = subFolders.next();
        node.folders.push(traverse(sub));
      }

      return node;
    }

    return traverse(root);
  }
}
